# visual style
navy="173B39"; teal="3F7C73"; pale="E9F1EE"; gray="F1F4F3"; white="FFFFFF"
thin=Side(style="thin",color="D2DDD8")
for sheet in wb.worksheets:
    sheet.freeze_panes="A2"
    sheet.auto_filter.ref=sheet.dimensions
    for c in sheet[1]:
        c.fill=PatternFill("solid",fgColor=navy);c.font=Font(color=white,bold=True);c.alignment=Alignment(wrap_text=True,vertical="center")
    sheet.row_dimensions[1].height=34
    for row in sheet.iter_rows(min_row=2):
        for c in row:
            c.alignment=Alignment(wrap_text=True,vertical="top")
            c.border=Border(bottom=thin)
            if c.row%2==0:c.fill=PatternFill("solid",fgColor=gray)
    sheet.sheet_view.showGridLines=False
    sheet.sheet_properties.pageSetUpPr.fitToPage=True
    sheet.page_setup.fitToWidth=1;sheet.page_setup.fitToHeight=0

widths={"Test Cases":[14,20,38,11,42,48,55,42,18],"Google Clock Comparison":[24,48,50,55,22,46],"Execution Summary":[25,115]}
for sheet in wb.worksheets:
    for i,w in enumerate(widths[sheet.title],1): sheet.column_dimensions[get_column_letter(i)].width=w
    for r in range(2,sheet.max_row+1):sheet.row_dimensions[r].height=65 if sheet.title!="Execution Summary" else 48
    if sheet.title=="Test Cases":
        for r in range(2,sheet.max_row+1):
            status=sheet.cell(r,9)
            status.fill=PatternFill("solid",fgColor="FCE4D6")
            status.font=Font(color="9C3B16",bold=True)
    if sheet.title=="Google Clock Comparison":
        for r in range(2,sheet.max_row+1):
            link=sheet.cell(r,6);link.hyperlink=link.value;link.style="Hyperlink"

